insert into positions(person, organization, title, start_date, start_date_precision, end_date, end_date_precision, urls, notes, employment_type, cause_area) values
('Holden Karnofsky', 'GiveWell', 'Co-founder', '2006-08-01', 'month', NULL, NULL, 'https://web.archive.org/web/20100609155532/https://www.givewell.org/about/people', 'June–September biographies explicitly date founding of the informal eight-person project to August 2006. October–November biographies instead date co-founding of GiveWell to mid-2007, reflecting the later organization. Earliest project origin retained; no exact day inferred.', NULL, 'Effective altruism'),
('Elie Hassenfeld', 'GiveWell', 'Co-founder', '2007-01-01', 'year', NULL, NULL, 'https://web.archive.org/web/20100609155532/https://www.givewell.org/about/people', 'October–November biographies explicitly state co-founded GiveWell in mid-2007. Earlier biography identifies him as an original volunteer in the informal project begun August 2006. Founding affiliation is separate from operational employment.', NULL, 'Effective altruism'),
('Holden Karnofsky', 'GiveWell', NULL, '2006-08-01', 'month', '2007-01-01', 'year', 'https://web.archive.org/web/20100609155532/https://www.givewell.org/about/people https://web.archive.org/web/20101120092215/https://www.givewell.org/about/people', 'Founded the informal part-time collaboration in August 2006; transitioned to full-time work in mid-2007. No operational title stated. End year follows the explicit transition, not disappearance from snapshots.', 'volunteer', 'Effective altruism'), /*Closed*/
('Elie Hassenfeld', 'GiveWell', NULL, '2006-08-01', 'month', '2007-08-01', 'month', 'https://web.archive.org/web/20100609155532/https://www.givewell.org/about/people https://web.archive.org/web/20101120092215/https://www.givewell.org/about/people', 'One of the original eight part-time volunteers in the project founded August 2006; left his previous job in August 2007 to work on GiveWell full-time. No operational title stated. Volunteer phase closed at the explicitly stated transition.', 'volunteer', 'Effective altruism'), /*Closed*/
('Holden Karnofsky', 'GiveWell', NULL, '2007-01-01', 'year', NULL, NULL, 'https://web.archive.org/web/20100609155532/https://www.givewell.org/about/people https://web.archive.org/web/20101120092215/https://www.givewell.org/about/people', 'Biography explicitly dates transition to full-time GiveWell work to mid-2007. No operational title supplied; executive titles are not inferred from outside background.', 'full-time', 'Effective altruism'), /*Last checked Wayback snapshot is from 2010-11-20*/
('Elie Hassenfeld', 'GiveWell', NULL, '2007-08-01', 'month', NULL, NULL, 'https://web.archive.org/web/20100609155532/https://www.givewell.org/about/people https://web.archive.org/web/20101120092215/https://www.givewell.org/about/people', 'Biography explicitly dates transition to full-time GiveWell work to August 2007. No operational title supplied.', 'full-time', 'Effective altruism'), /*Last checked Wayback snapshot is from 2010-11-20*/
('Natalie Stone', 'GiveWell', 'Research Analyst', '2009-07-01', 'month', NULL, NULL, 'https://web.archive.org/web/20100609155532/https://www.givewell.org/about/people https://web.archive.org/web/20101120092215/https://www.givewell.org/about/people', 'Biography explicitly states joined as Research Analyst in July 2009; listed under Full-time staff.', 'full-time', 'Effective altruism'), /*Last checked Wayback snapshot is from 2010-11-20*/
('Simon Knutsson', 'GiveWell', NULL, '2008-01-01', 'year', NULL, NULL, 'https://web.archive.org/web/20100609155532/https://www.givewell.org/about/people https://web.archive.org/web/20101120092215/https://www.givewell.org/about/people', 'Biography states volunteer work since summer 2008, without a title or a volunteer end date. Summer Research Consultant engagement is recorded separately; cessation of volunteering is not explicitly stated.', 'volunteer', 'Effective altruism'), /*Last checked Wayback snapshot is from 2010-11-20*/
('Simon Knutsson', 'GiveWell', 'Research Consultant', '2010-01-01', 'year', NULL, NULL, 'https://web.archive.org/web/20100609155532/https://www.givewell.org/about/people https://web.archive.org/web/20101120092215/https://www.givewell.org/about/people', 'Biography explicitly describes a Research Consultant engagement for summer 2010. Season is represented at year precision; no exact start or end inferred. The same description remains on all six supplied snapshots through November, so the listing alone does not establish a completed contract end. Consultant classification follows the explicit title despite placement under Full-time staff.', 'contractor', 'Effective altruism'), /*Last checked Wayback snapshot is from 2010-11-20*/
